def compute_interference(tau_j, a, b):
    total_interference = 0
    for tau_i in higher_priority_tasks(tau_j):
        interference_i = compute_task_interference(tau_i, tau_j, a, b)
        total_interference += interference_i
    return total_interference / m

def compute_zero_laxity_bound(tau_i):
    v_min, v_max = 0, tau_i.C
    while v_max - v_min > epsilon:
        v = (v_min + v_max) / 2
        if is_schedulable(tau_i, tau_i.C - v, tau_i.D - v):
            v_max = v
        else:
            v_min = v
    return v_min

def DA_LC_test_FPZL(taskset, m):
    for tau_k in taskset:
        total_interference = 0
        for tau_i in higher_priority(tau_k):
            I_i_k = compute_interference(tau_i, tau_k, tau_k.D)
            total_interference += min(I_i_k, tau_k.D - tau_k.C + 1)
        for tau_j in zero_laxity_tasks(tau_k):
            I_j_k = compute_ZL_interference(tau_j, tau_k, tau_k.D)
            total_interference += min(I_j_k, tau_k.D - tau_k.C + 1)
        if total_interference >= m * (tau_k.D - tau_k.C + 1):
            return False
    return True

def verify_DC_sustainability(tau_k, v, w):
    assert v <= w <= tau_k.C
    if is_schedulable(tau_k, tau_k.C - v, tau_k.D - v):
        assert is_schedulable(tau_k, tau_k.C - w, tau_k.D - w)
    return True
